#!/usr/bin/env bash
# Refreshes the vendored API spec from the live website.
#
#     scripts/sync-openapi.sh            # from https://www.trackdown.nl
#     scripts/sync-openapi.sh http://localhost:5173
#
# The spec is generated by trackdown-website (openapi/v1.json there). The
# Swift OpenAPI Generator build plugin turns it into the TrackdownAPI client,
# so commit the refreshed file together with any code it breaks.
set -euo pipefail

base_url="${1:-https://www.trackdown.nl}"
repo_root="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
destination="$repo_root/Packages/TrackdownAPI/openapi/v1.json"
temporary="$(mktemp)"
trap 'rm -f "$temporary"' EXIT

# The spec is the one endpoint that needs no client headers.
curl --fail --silent --show-error --location "$base_url/api/v1/openapi.json" --output "$temporary"

# Pretty-print so spec changes show up as readable diffs. Fails on invalid JSON.
jq . "$temporary" > "$destination"

echo "Updated ${destination#"$repo_root"/} from $base_url"
